describe('Login Form CAPTCHA After Failed Attempts', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should display CAPTCHA after 3 consecutive failed login attempts', () => {
    // First failed attempt
    cy.get('[data-testid="email-input"]').type('invalid-email@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="login-error-message"]').should('be.visible').should('contain', 'Invalid credentials');

    // Second failed attempt
    cy.get('[data-testid="email-input"]').type('invalid-email@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="login-error-message"]').should('be.visible').should('contain', 'Invalid credentials');

    // Third failed attempt
    cy.get('[data-testid="email-input"]').type('invalid-email@example.com');
    cy.get('[data-testid="password-input"]').type('wrongpassword');
    cy.get('[data-testid="login-button"]').click();

    // Verify CAPTCHA is displayed
    cy.get('[data-testid="captcha-container"]').should('be.visible');
    cy.get('[data-testid="captcha-image"]').should('contain', 'Verify you are human');
    cy.get('[data-testid="captcha-input"]').should('be.visible');

    // Verify CAPTCHA input is enabled
    cy.get('[data-testid="captcha-input"]').should('not.be.disabled');

    // Verify CAPTCHA verification button is visible
    cy.get('[data-testid="captcha-verify-button"]').should('be.visible');

    // Verify CAPTCHA verification button is disabled
    cy.get('[data-testid="captcha-verify-button"]').should('be.disabled');

    // Verify login button is still visible but disabled
    cy.get('[data-testid="login-button"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('be.disabled');
  });

  it('should not display CAPTCHA after successful login or after resetting failed attempts', () => {
    // Reset failed attempts
    cy.get('[data-testid="reset-failed-attempts-button"]').click();
    cy.get('[data-testid="reset-failed-attempts-success-message"]').should('be.visible').should('contain', 'Failed attempts reset');

    // Verify CAPTCHA is no longer visible
    cy.get('[data-testid="captcha-container"]').should('not.exist');

    // Verify login button is enabled
    cy.get('[data-testid="login-button"]').should('be.enabled');

    // Attempt successful login
    cy.get('[data-testid="email-input"]').type('valid-email@example.com');
    cy.get('[data-testid="password-input"]').type('correctpassword');
    cy.get('[data-testid="login-button"]').click();

    // Verify login success message appears
    cy.get('[data-testid="login-success-message"]').should('be.visible').should('contain', 'Login successful');

    // Verify CAPTCHA is still not visible after successful login
    cy.get('[data-testid="captcha-container"]').should('not.exist');
  });
});
